/**
 * Cascade behind `ProjectService.archiveProject`. Stamps only issues that are
 * still live and returns how many were newly archived. Issues archived earlier
 * keep their original `archived_at`, and issues in other projects are left alone.
 */
export async function archiveIssuesForProject(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const rows = getDb()
    .update(issues)
    .set(archivePatch())
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          eq(issues.projectId, projectId),
          livePredicate(issues.archivedAt, {}),
        ),
      ),
    )
    .returning({ id: issues.id })
    .all();

  return rows.length;
}

